package com.bplus.share;
import org.json.*;import java.io.*;import java.net.*;import java.util.*;
/** Additive authenticated LAN text queue protocol. Local HTTP remains trusted-LAN only. */
public final class LanSync {
 public static JSONObject profile()throws Exception{JSONObject p=Profile.local();p.remove("photo");return p;}
 private static JSONObject base()throws Exception{return new JSONObject().put("v",2).put("profile",profile()).put("capabilities",new JSONArray().put("durable-text").put("receipts").put("profile").put("pairing-unpair-v1"));}
 public static JSONObject call(JSONObject peer,JSONObject b)throws Exception{if(b.optString("op").equals("hello"))b.put("profile",Profile.local().put("photoHash",PhotoSync.hash(Store.get("photo",""))));b.put("v",2).put("from",Store.get("deviceId","")).put("senderToken",Store.token()).put("targetToken",peer.getString("token"));HttpURLConnection h=(HttpURLConnection)new URL("http://"+peer.getString("ip")+":"+peer.optInt("port",Store.PORT)+"/sync").openConnection();h.setConnectTimeout(2500);h.setReadTimeout(4000);try{h.setRequestMethod("POST");h.setDoOutput(true);h.setRequestProperty("Content-Type","application/json");byte[] raw=b.toString().getBytes("UTF-8");h.setFixedLengthStreamingMode(raw.length);try(OutputStream out=h.getOutputStream()){out.write(raw);}if(h.getResponseCode()!=200)throw new IOException("Sync HTTP "+h.getResponseCode());ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=h.getInputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>48000)throw new IOException("Sync response too large");}}JSONObject reply=new JSONObject(out.toString("UTF-8"));if(Unpair.reply(reply,peer))throw new IOException("Peer unpaired");JSONObject p=reply.getJSONObject("profile");if(reply.optInt("v")!=2||!peer.getString("id").equals(p.optString("id")))throw new IOException("Wrong sync peer");Store.refreshProfile(peer.getString("id"),p);return reply;}finally{h.disconnect();}}
 public static synchronized JSONObject handle(JSONObject b,String ip)throws Exception{if(b.optInt("v")!=2||!Store.token().equals(b.optString("targetToken")))throw new IOException("Wrong sync target");JSONObject notice=Unpair.hello(b);if(notice!=null)return notice;String from=b.optString("from");Recall.authenticate(Store.peerById(from),ip,b.optString("senderToken"));JSONObject out=base();String op=b.optString("op");if(op.equals("hello")){if(b.has("profile")){JSONObject incoming=b.getJSONObject("profile");if(!from.equals(incoming.optString("id")))throw new IOException("Wrong profile identity");Store.refreshProfile(from,incoming);}out.put("profile",Profile.local().put("photoHash",PhotoSync.hash(Store.get("photo",""))));return out;}if(op.equals("send")){String wire=b.optString("wire"),key=b.optString("key"),text=b.optString("text");if(!Recall.valid(wire)||!Recall.valid(key)||text.isEmpty()||text.length()>8000)throw new IOException("Invalid text envelope");String raw=Store.get(Recall.ledger(from,wire),"");if(!raw.isEmpty()){JSONObject receipt=new JSONObject(raw);if(!key.equals(receipt.optString("key")))throw new IOException("Receipt collision");return out.put("wire",wire).put("status",receipt.optString("status").equals("deleted")?"deleted":receipt.optBoolean("read")?"read":"delivered");}JSONObject msg=new JSONObject().put("kind","text").put("body",text).put("wireId",wire).put("me",false).put("ts",System.currentTimeMillis()).put("state","received");JSONObject receipt=new JSONObject().put("key",key).put("kind","text").put("uri","").put("status","received");Store.receiveAtomic(from,wire,msg,receipt);Alerts.message(Store.peerById(from).optString("name"),msg);TransferService.changed(from);return out.put("wire",wire).put("status","delivered");}if(op.equals("status")){JSONArray items=b.getJSONArray("items");if(items.length()>100)throw new IOException("Too many receipts");JSONArray result=new JSONArray();for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);String wire=item.optString("wire"),key=item.optString("key");if(!Recall.valid(wire)||!Recall.valid(key))throw new IOException("Invalid receipt");String raw=Store.get(Recall.ledger(from,wire),"");String status="unknown";if(!raw.isEmpty()){JSONObject receipt=new JSONObject(raw);if(!key.equals(receipt.optString("key")))throw new IOException("Wrong receipt key");status=receipt.optString("status").equals("deleted")?"deleted":receipt.optBoolean("read")?"read":"delivered";}result.put(new JSONObject().put("wire",wire).put("status",status));}return out.put("items",result);}throw new IOException("Unknown sync operation");}
 public static synchronized void read(String peer,String wire){if(!Recall.valid(wire))return;try{String slot=Recall.ledger(peer,wire),raw=Store.get(slot,"");if(raw.isEmpty())return;JSONObject r=new JSONObject(raw);if(!r.optBoolean("read")){r.put("read",true);Store.durable(slot,r.toString());}}catch(Exception ignored){}}
}
